/* The core device model and type registry (core/src/dev/device.c).
 * Run: ninja check-device
 *
 * The registry this test links is generated by configure from
 * tests/data/device/test-*.xml: the three types below. */
#include "gemu/dev/device.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static unsigned checks;
#define CHECK(expr) do { checks++; if (!(expr)) { \
    fprintf(stderr, "%s:%d: %s\n", __FILE__, __LINE__, #expr); exit(1); \
} } while (0)

/* Every hook appends "<event>:<path>" to the log. */
static char log_buf[4096];
static void logf_(const char *ev, GemuDevice *d) {
    size_t n = strlen(log_buf);
    snprintf(log_buf + n, sizeof log_buf - n, "%s%s:%s", n ? " " : "", ev, d->path);
}
static void log_clear(void) { log_buf[0] = 0; }

typedef struct { int inits, resets; GemuResetKind last; unsigned magic; } LeafState;

static bool leaf_init(GemuDevice *d) {
    LeafState *s = d->priv;
    CHECK(s->inits == 0 && s->magic == 0);     /* priv starts zeroed */
    s->inits++;
    s->magic = 0x1234;
    logf_("init", d);
    return true;
}
static void leaf_reset(GemuDevice *d, GemuResetKind k) {
    LeafState *s = d->priv;
    s->resets++;
    s->last = k;
    logf_("reset", d);
}
static void leaf_destroy(GemuDevice *d) { logf_("destroy", d); }
static void leaf_describe(GemuDevice *d, char *buf, size_t len) {
    snprintf(buf, len, "leaf %s, %d resets", d->path, ((LeafState *)d->priv)->resets);
}

const GemuDeviceType test_leaf_type = {
    .name = "test-leaf", .desc = "A device-model test type", .size = sizeof(LeafState),
    .init = leaf_init, .reset = leaf_reset, .destroy = leaf_destroy,
    .describe = leaf_describe,
};

static bool bus_init(GemuDevice *d) { logf_("init", d); return true; }
static void bus_reset(GemuDevice *d, GemuResetKind k) { (void)k; logf_("reset", d); }
static void bus_after(GemuDevice *d, GemuResetKind k) { (void)k; logf_("after", d); }
static void bus_destroy(GemuDevice *d) { logf_("destroy", d); }

const GemuDeviceType test_bus_type = {
    .name = "test-bus", .desc = "A device-model test type with children",
    .init = bus_init, .reset = bus_reset, .reset_after_children = bus_after,
    .destroy = bus_destroy,
};

static bool broken_init(GemuDevice *d) {
    logf_("init", d);
    gemu_device_error(d, "no %s today", "hardware");
    return false;
}
static void broken_destroy(GemuDevice *d) { logf_("destroy", d); }

const GemuDeviceType test_broken_type = {
    .name = "test-broken", .desc = "A device-model test type whose init fails",
    .init = broken_init, .destroy = broken_destroy,
};

/* Not in the registry: added by pointer.  No hooks, no state. */
static const GemuDeviceType bare_type = { .name = "bare" };

static bool count_cb(GemuDevice *d, void *ud) { (void)d; ++*(int *)ud; return true; }
static bool paths_cb(GemuDevice *d, void *ud) {
    char *s = ud;
    size_t n = strlen(s);
    snprintf(s + n, 512 - n, "[%s]", d->path);
    return true;
}
static bool stop_cb(GemuDevice *d, void *ud) { ++*(int *)ud; return strcmp(d->path, "isa") != 0; }

int main(void) {
    /* ── Registry ── */
    CHECK(gemu_device_type_count() == 3);
    CHECK(gemu_device_type_find("test-leaf") == &test_leaf_type);
    CHECK(gemu_device_type_find("test-bus") == &test_bus_type);
    CHECK(gemu_device_type_find("test-broken") == &test_broken_type);
    CHECK(!gemu_device_type_find("bare") && !gemu_device_type_find("") &&
          !gemu_device_type_find(NULL) && !gemu_device_type_find("test-lea"));
    for (size_t i = 0; i < gemu_device_type_count(); i++) {
        const GemuDeviceType *t = gemu_device_type_at(i);
        /* the XML name is the type's own name; the table is sorted */
        CHECK(gemu_device_type_find(t->name) == t);
        if (i)
            CHECK(strcmp(gemu_device_type_at(i - 1)->name, t->name) < 0);
    }
    CHECK(!gemu_device_type_at(3));

    /* ── Building a tree ── */
    GemuMachine *m = gemu_machine_new("testpc");
    CHECK(m && !strcmp(gemu_machine_name(m), "testpc") && !gemu_machine_started(m));
    GemuDevice *root = gemu_machine_root(m);
    CHECK(root && root->path[0] == 0 && !root->parent && !root->type);
    CHECK(gemu_device_find(m, "") == root);

    GemuDevice *board = gemu_device_add_type(m, "test-bus", "board", NULL, NULL);
    GemuDevice *pic = gemu_device_add_type(m, "test-leaf", "pic", board, "irq=2");
    GemuDevice *pit = gemu_device_add(m, &test_leaf_type, "pit", board, NULL);
    GemuDevice *isa = gemu_device_add(m, &test_bus_type, "isa", NULL, NULL);
    GemuDevice *adlib = gemu_device_add_type(m, "test-leaf", "adlib", isa, NULL);
    GemuDevice *bare = gemu_device_add(m, &bare_type, "bare.0", isa, NULL);
    CHECK(board && pic && pit && isa && adlib && bare);
    CHECK(!strcmp(pic->path, "board/pic") && !strcmp(pic->name, "pic"));
    CHECK(!strcmp(adlib->path, "isa/adlib") && adlib->parent == isa && adlib->machine == m);
    CHECK(!strcmp(pic->opts, "irq=2") && !pit->opts);
    CHECK(bare->priv == NULL && ((LeafState *)pic->priv)->magic == 0);
    CHECK(board->priv == NULL);                         /* size 0 */
    CHECK(log_buf[0] == 0);                             /* nothing runs before start */
    CHECK(board->first_child == pic && pic->next_sibling == pit && !pit->next_sibling);
    CHECK(root->first_child == board && root->last_child == isa);

    /* Errors: the machine's message says what went wrong. */
    CHECK(!gemu_device_add(m, &test_leaf_type, "pic", board, NULL));
    CHECK(strstr(gemu_machine_error(m), "board/pic: already exists"));
    CHECK(gemu_device_add(m, &test_leaf_type, "pic", isa, NULL));   /* elsewhere: fine */
    gemu_device_destroy(gemu_device_find(m, "isa/pic"));
    CHECK(!gemu_device_add(m, &test_leaf_type, "a/b", NULL, NULL));
    CHECK(strstr(gemu_machine_error(m), "not a valid device name"));
    CHECK(!gemu_device_add(m, &test_leaf_type, "", NULL, NULL));
    CHECK(!gemu_device_add(m, &test_leaf_type, "..", NULL, NULL));
    CHECK(!gemu_device_add(m, &test_leaf_type, NULL, NULL, NULL));
    CHECK(!gemu_device_add(m, NULL, "x", NULL, NULL));
    CHECK(!gemu_device_add_type(m, "sb16", "sb", isa, NULL));
    CHECK(strstr(gemu_machine_error(m), "no device type \"sb16\""));
    char longname[80];
    memset(longname, 'x', sizeof longname - 1);
    longname[sizeof longname - 1] = 0;
    CHECK(!gemu_device_add(m, &test_leaf_type, longname, NULL, NULL));
    CHECK(strstr(gemu_machine_error(m), "path longer than"));
    longname[GEMU_DEVICE_PATH_MAX - 5] = 0;           /* "isa/" + 59 = 63: fits */
    GemuDevice *lng = gemu_device_add(m, &bare_type, longname, isa, NULL);
    CHECK(lng && strlen(lng->path) == GEMU_DEVICE_PATH_MAX - 1);
    CHECK(!gemu_device_add(m, &bare_type, "y", lng, NULL));   /* its child won't */
    gemu_device_destroy(lng);
    GemuMachine *other = gemu_machine_new("other");
    CHECK(!gemu_device_add(other, &bare_type, "z", isa, NULL));
    CHECK(strstr(gemu_machine_error(other), "another machine"));
    gemu_machine_free(other);

    /* ── Finding devices ── */
    CHECK(gemu_device_find(m, "board/pic") == pic);
    CHECK(gemu_device_find(m, "isa/bare.0") == bare);
    CHECK(gemu_device_find(m, "board") == board);
    CHECK(!gemu_device_find(m, "board/pic/x") && !gemu_device_find(m, "pic"));
    CHECK(!gemu_device_find(m, "board/") && !gemu_device_find(m, "/board") &&
          !gemu_device_find(m, "board//pic") && !gemu_device_find(m, "board/pi"));
    CHECK(gemu_device_lookup(pic, "..") == board);
    CHECK(gemu_device_lookup(pic, "../pit") == pit);
    CHECK(gemu_device_lookup(pic, "../../isa/adlib") == adlib);
    CHECK(gemu_device_lookup(pic, ".") == pic && gemu_device_lookup(pic, "") == pic);
    CHECK(gemu_device_lookup(board, "pit") == pit);
    CHECK(!gemu_device_lookup(root, ".."));
    CHECK(gemu_device_lookup(root, "./isa/./adlib") == adlib);

    int n = 0;
    CHECK(gemu_device_walk(root, count_cb, &n) && n == 7);
    char paths[512] = "";
    gemu_device_walk(root, paths_cb, paths);
    CHECK(!strcmp(paths, "[][board][board/pic][board/pit][isa][isa/adlib][isa/bare.0]"));
    n = 0;
    CHECK(!gemu_device_walk(root, stop_cb, &n) && n == 5);

    /* Clocks inherit from the nearest ancestor that has one. */
    CHECK(gemu_device_clock(pic) == 0);
    gemu_device_set_clock(board, 4772727);
    gemu_device_set_clock(pit, 1193182);
    CHECK(gemu_device_clock(pic) == 4772727 && gemu_device_clock(pit) == 1193182);
    CHECK(gemu_device_clock(adlib) == 0);

    /* Reset before start does nothing. */
    gemu_machine_reset(m, GEMU_RESET_HARD);
    CHECK(log_buf[0] == 0);

    /* ── Start: init pre-order, then a power-on reset ── */
    CHECK(gemu_machine_start(m) && gemu_machine_started(m));
    CHECK(!strcmp(log_buf,
        "init:board init:board/pic init:board/pit init:isa init:isa/adlib "
        "reset:board reset:board/pic reset:board/pit after:board "
        "reset:isa reset:isa/adlib after:isa"));
    LeafState *ps = pic->priv;
    CHECK(ps->inits == 1 && ps->resets == 1 && ps->last == GEMU_RESET_POWER_ON);
    CHECK(gemu_machine_start(m));                       /* twice: no-op */
    CHECK(ps->inits == 1 && ps->resets == 1);

    /* Reset of the machine and of a subtree. */
    log_clear();
    gemu_machine_reset(m, GEMU_RESET_SOFT);
    CHECK(ps->resets == 2 && ps->last == GEMU_RESET_SOFT);
    log_clear();
    gemu_device_reset(board, GEMU_RESET_HARD);
    CHECK(!strcmp(log_buf, "reset:board reset:board/pic reset:board/pit after:board"));
    CHECK(ps->last == GEMU_RESET_HARD && ((LeafState *)adlib->priv)->resets == 2);

    char desc[128];
    gemu_device_describe(pic, desc, sizeof desc);
    CHECK(!strcmp(desc, "leaf board/pic, 3 resets"));
    gemu_device_describe(isa, desc, sizeof desc);
    CHECK(!strcmp(desc, "test-bus: A device-model test type with children"));
    gemu_device_describe(root, desc, sizeof desc);
    CHECK(!strcmp(desc, "machine testpc"));

    /* ── Hot-plug: a device added to a running machine starts at once ── */
    log_clear();
    GemuDevice *sb = gemu_device_add_type(m, "test-leaf", "sb", isa, NULL);
    CHECK(sb && !strcmp(log_buf, "init:isa/sb reset:isa/sb"));
    CHECK(((LeafState *)sb->priv)->last == GEMU_RESET_POWER_ON);
    CHECK(isa->last_child == sb);
    /* ... and one whose init fails is not added. */
    log_clear();
    CHECK(!gemu_device_add_type(m, "test-broken", "bad", isa, NULL));
    CHECK(!strcmp(log_buf, "init:isa/bad"));            /* no destroy: never started */
    CHECK(!strcmp(gemu_machine_error(m), "isa/bad: no hardware today"));
    CHECK(!gemu_device_find(m, "isa/bad") && isa->last_child == sb);

    /* ── Destroy: children first, last added first ── */
    log_clear();
    gemu_device_destroy(isa);
    CHECK(!strcmp(log_buf, "destroy:isa/sb destroy:isa/adlib destroy:isa"));
    CHECK(!gemu_device_find(m, "isa") && root->last_child == board && !board->next_sibling);
    /* the name is free again */
    log_clear();
    GemuDevice *isa2 = gemu_device_add(m, &test_bus_type, "isa", NULL, NULL);
    CHECK(isa2 && !strcmp(log_buf, "init:isa reset:isa after:isa"));
    gemu_device_destroy(root);                          /* the root: ignored */
    CHECK(gemu_device_find(m, "board/pit") == pit);
    gemu_device_destroy(pit);                           /* a middle child */
    CHECK(board->first_child == pic && board->last_child == pic && !pic->next_sibling);

    log_clear();
    gemu_machine_free(m);
    CHECK(!strcmp(log_buf, "destroy:isa destroy:board/pic destroy:board"));

    /* ── A failing init stops the start; only started devices are destroyed ── */
    m = gemu_machine_new("broken");
    gemu_device_add_type(m, "test-leaf", "a", NULL, NULL);
    GemuDevice *bad = gemu_device_add_type(m, "test-broken", "b", NULL, NULL);
    gemu_device_add_type(m, "test-leaf", "c", bad, NULL);
    gemu_device_add_type(m, "test-leaf", "d", NULL, NULL);
    log_clear();
    CHECK(!gemu_machine_start(m) && !gemu_machine_started(m));
    CHECK(!strcmp(log_buf, "init:a init:b"));
    CHECK(!strcmp(gemu_machine_error(m), "b: no hardware today"));
    log_clear();
    gemu_machine_free(m);
    CHECK(!strcmp(log_buf, "destroy:a"));
    gemu_machine_free(NULL);

    printf("device: %u checks passed\n", checks);
    return 0;
}
